/* teste do desafio quantos-aprovados — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: nao ha captura de stdout aqui. O teste declara o prototipo da
   caixa do aluno, chama-a com tres cortes diferentes e confere o VALOR
   devolvido com checa_int. A lista e fixa e o corte e que muda: uma caixa
   que devolvesse um numero fixo reprovaria em dois dos tres cenarios. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
int quantosAprovados(int corte);

SM_TEST(quatro_alcancam_o_corte_6) {
    checa_int("com corte 6, quatro notas alcancam", quantosAprovados(6), 4,
              "7, 10, 6 e 9 sao maiores ou iguais a 6; 5 e 4 ficam de fora");
}

SM_TEST(duas_alcancam_o_corte_9) {
    checa_int("com corte 9, duas notas alcancam", quantosAprovados(9), 2,
              "subir o corte derruba a contagem: so 10 e 9 alcancam o 9");
}

SM_TEST(ninguem_alcanca_o_corte_11) {
    checa_int("com corte 11, ninguem alcanca", quantosAprovados(11), 0,
              "nenhuma nota chega a 11, e o contador termina como comecou: em zero");
}

solutionCode:
int quantosAprovados(int corte) {
    int notas[6] = {7, 5, 10, 6, 4, 9};
    int total = 0;

    for (int i = 0; i < 6; i++) {
        if (notas[i] >= corte) {
            total += 1;
        }
    }

    return total;
}
